MI1_inverse_back_to_private_regex.from:
const term = Namespace.fromTermIRI(iri);
if (term) {
  return `${term.namespace.prefix}__${term.localName}`;
}
return iri;

MI1_inverse_back_to_private_regex.to:
const match = iri.match(/https:\/\/exocortex\.my\/ontology\/([a-z]+)#(.+)$/);
if (match) {
  return `${match[1]}__${match[2]}`;
}
return iri;

MI2_forward_back_to_private_switch.from:
const parsed = Namespace.fromPropertyKey(propertyName);
if (parsed) {
  return parsed.namespace.term(parsed.localName).value;
}

return propertyName;

MI2_forward_back_to_private_switch.to:
const match = propertyName.match(/^([a-z]+)__(.+)$/);
if (match) {
  return `https://exocortex.my/ontology/${match[1]}#${match[2]}`;
}

return propertyName;

